/**
 * MultiSelect.Chip: one chosen value, with its remove button, playing its exit when it is removed.
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/multi-select.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { createMemo, type JSX } from 'solid-js'

import { Icon, claimSlot, elementRef, scope, watchEffect } from '@polymorph/solid'
import { usePresence } from '@polymorph/solid/motion'
import styles from '@polymorph/recipes/controls/multi-select.module.css'

export interface MultiSelectChipProps {
  label: string
  /**
   * False once the value is removed, while the chip plays its exit.
   */
  open: boolean
  /**
   * The chip joined after the list’s first render, so it plays its enter.
   */
  appear: boolean
  disabled: boolean
  /**
   * The remove button’s accessible name.
   */
  removeLabel: string
  onRemove?: () => void
  onKeyDown?: (event: KeyboardEvent) => void
  /**
   * The exit has played, and the member can drop the chip.
   */
  onDone?: () => void
}

/** MultiSelect.Chip: one chosen value, with its remove button, playing its exit when it is removed. */
export default function MultiSelectChip(given: MultiSelectChipProps): JSX.Element {
  const props = claimSlot(given)
  return scope(() => {
    const chip = elementRef<HTMLElement>()
    const present = usePresence(
      () => props.open,
      () => chip.value,
      'taginput.chip',
      {
        get appear() {
          return props.appear
        },
        reflow: 'taginput.reflow',
      },
    )
    const effect1 = () => {
      void (present() || props.onDone?.())
    }
    watchEffect(
      createMemo(() => present()),
      effect1,
      false,
    )
    return (
      <li class={styles.chip} data-removing={!props.open ? '' : undefined} ref={chip.attach}>
        {/* label */}
        <span class={styles.label}>{props.label}</span>
        {!props.disabled ? (
          <button
            class={styles.remove}
            type="button"
            aria-label={props.removeLabel}
            onclick={() => props.onRemove?.()}
            onkeydown={($event: KeyboardEvent) => props.onKeyDown?.($event)}
          >
            <Icon name="close" size="sm" />
          </button>
        ) : null}
      </li>
    )
  })
}
